"""Static inference.

Secret: how bindings and expressions are mapped to values (modules, classes,
functions, instances), how names are resolved through scopes, flow states,
star imports and builtins, how narrowing conditions restrict values, and how
the members of a value are enumerated.

Clients see these abstractions:
  * ``Project``  - opens the main file and returns a ``Location`` for a cursor.
  * ``Where``    - an evaluation point: a scope plus the flow state there.
  * ``Value``    - has ``kind``, ``type_name`` and ``members()``; evaluation
                   always yields a list of possible values (a union).
  * ``Entity``   - a named member/visible name with ``presentation()`` giving
                   ``(kind, type_name)`` and ``values()`` giving its values.
Name resolution yields *targets*: ``scopes.Binding`` objects for names bound
in source, or ``Entity`` objects for names provided at runtime.
"""

import ast
import builtins
import io
import os
import types

from . import flow, introspect, scopes, vocabulary
from .modules import DIRECTORY, RUNTIME, SOURCE, ModuleLocator

MODULE = "module"
CLASS = "class"
FUNCTION = "function"
INSTANCE = "instance"
PARAM = "param"
STATEMENT = "statement"
UNKNOWN = "unknown"

_LITERAL_TYPES = {
    ast.JoinedStr: str,
    ast.ListComp: list,
    ast.DictComp: dict,
    ast.SetComp: set,
    ast.GeneratorExp: types.GeneratorType,
    ast.Compare: bool,
}
_SEQUENCE_TYPES = {ast.List: list, ast.Tuple: tuple, ast.Set: set}
_ARITHMETIC_TYPES = (int, float, complex, str, bytes, list, tuple)
_PROPERTY_DECORATORS = ("property", "cached_property")

_FUNCTION_RETURNS = {
    "len": int, "repr": str, "ascii": str, "chr": str, "ord": int, "hash": int, "id": int,
    "input": str, "format": str, "bin": str, "oct": str, "hex": str, "isinstance": bool,
    "issubclass": bool, "callable": bool, "hasattr": bool, "all": bool, "any": bool,
    "sorted": list, "dir": list, "vars": dict, "globals": dict, "locals": dict,
    "round": int, "divmod": tuple, "open": io.TextIOWrapper,
}
_FUNCTION_RETURNS = {getattr(builtins, name): result
                     for name, result in _FUNCTION_RETURNS.items() if hasattr(builtins, name)}


def _method_table():
    table = {}

    def add(owner, result, names):
        for name in names.split():
            table[(owner, name)] = result

    add(str, str, "upper lower strip lstrip rstrip replace format join title capitalize "
                  "casefold center ljust rjust zfill swapcase expandtabs removeprefix "
                  "removesuffix translate format_map")
    add(str, list, "split rsplit splitlines")
    add(str, bool, "startswith endswith isalpha isdigit isalnum isspace islower isupper "
                   "istitle isdecimal isnumeric isidentifier isprintable isascii")
    add(str, int, "find rfind index rindex count")
    add(str, bytes, "encode")
    add(str, tuple, "partition rpartition")
    add(bytes, str, "decode hex")
    add(bytes, bytes, "upper lower strip lstrip rstrip replace join")
    add(bytes, list, "split rsplit splitlines")
    add(list, list, "copy")
    add(list, int, "index count")
    add(tuple, int, "index count")
    add(dict, dict, "copy")
    add(dict, type({}.keys()), "keys")
    add(dict, type({}.values()), "values")
    add(dict, type({}.items()), "items")
    add(set, set, "copy union intersection difference symmetric_difference")
    add(set, bool, "issubset issuperset isdisjoint")
    add(frozenset, frozenset, "copy union intersection difference symmetric_difference")
    add(int, int, "bit_length bit_count conjugate")
    add(int, bytes, "to_bytes")
    add(float, bool, "is_integer")
    add(float, str, "hex")
    return table


_METHOD_RETURNS = _method_table()


class _Slice:
    """Marker for a slice subscript."""


SLICE = _Slice()
UNKNOWN_INDEX = _Slice()


# ---------------------------------------------------------------------------
# Evaluation points

class Where:
    """A scope plus the flow state (None: the state at the end of the scope)."""

    def __init__(self, scope, state=None):
        self.scope = scope
        self.state = state


def _unique(values):
    seen = set()
    result = []
    for value in values:
        key = value.key()
        if key not in seen:
            seen.add(key)
            result.append(value)
    return result


# ---------------------------------------------------------------------------
# Values

class Value:
    kind = UNKNOWN
    type_name = None

    def key(self):
        return ("value", id(self))

    def members(self):
        return {}

    def attribute(self, name):
        entity = self.members().get(name)
        return entity.values() if entity is not None else []

    def attribute_targets(self, name):
        """Where attribute ``name`` is bound (Bindings or Entities)."""
        entity = self.members().get(name)
        return [entity] if entity is not None else []

    def call(self):
        return []

    def instantiate(self):
        return []

    def iterate(self):
        return []

    def subscript(self, index):
        return []

    def builtin_type(self):
        """For instances of builtin types, the type object; else None."""
        return None


class RuntimeValue(Value):
    """A live object obtained by importing a module."""

    def __init__(self, project, obj, owner=None):
        self.project = project
        self.obj = obj
        self._owner = owner
        self.kind = introspect.kind_of(obj)
        if self.kind == INSTANCE:
            self.type_name = introspect.type_name(obj)

    def key(self):
        return ("runtime", id(self.obj))

    def members(self):
        return {name: RuntimeEntity(self.project, name, self.obj)
                for name in introspect.attribute_names(self.obj)}

    def attribute(self, name):
        ok, value = introspect.get_attribute(self.obj, name)
        if ok:
            owner = self.obj if self.kind == CLASS else type(self.obj)
            return [RuntimeValue(self.project, value, owner)]
        if self.kind == MODULE:
            module_name = getattr(self.obj, "__name__", None)
            if module_name:
                found = self.project.module_value(module_name + "." + name)
                if found is not None:
                    return [found]
        return []

    def attribute_targets(self, name):
        ok, _ = introspect.get_attribute(self.obj, name)
        if ok:
            return [RuntimeEntity(self.project, name, self.obj)]
        return [_ValueTarget(v) for v in self.attribute(name)]

    def call(self):
        if self.kind == CLASS:
            return self.instantiate()
        if self.kind == FUNCTION:
            try:
                result = _FUNCTION_RETURNS.get(self.obj)
            except TypeError:
                result = None
            if result is None and self._owner is not None:
                result = _method_return(self._owner, getattr(self.obj, "__name__", None))
            if result is not None:
                return [RuntimeInstance(self.project, result)]
        return []

    def instantiate(self):
        if self.kind == CLASS:
            return [RuntimeInstance(self.project, self.obj)]
        return []

    def iterate(self):
        if self.kind == INSTANCE:
            return RuntimeInstance(self.project, type(self.obj)).iterate()
        return []

    def subscript(self, index):
        if self.kind == CLASS:
            return [self]
        if self.kind == INSTANCE:
            return RuntimeInstance(self.project, type(self.obj)).subscript(index)
        return []

    def builtin_type(self):
        return type(self.obj) if self.kind == INSTANCE else None


def _method_return(owner, name):
    if not name or not isinstance(owner, type):
        return None
    for base in getattr(owner, "__mro__", (owner,)):
        result = _METHOD_RETURNS.get((base, name))
        if result is not None:
            return result
    return None


class RuntimeInstance(Value):
    """An instance of a runtime class, known only by its class."""

    kind = INSTANCE

    def __init__(self, project, cls):
        self.project = project
        self.cls = cls
        self._sample = introspect.sample_instance(cls)
        self.type_name = introspect.class_name(cls)

    def key(self):
        return ("instance", id(self.cls))

    def members(self):
        return {name: RuntimeEntity(self.project, name, self._sample, from_class=self.cls)
                for name in introspect.attribute_names(self.cls)}

    def attribute(self, name):
        return RuntimeEntity(self.project, name, self._sample, from_class=self.cls).values()

    def attribute_targets(self, name):
        if name in introspect.attribute_names(self.cls):
            return [RuntimeEntity(self.project, name, self._sample, from_class=self.cls)]
        return []

    def iterate(self):
        if issubclass(self.cls, str):
            return [RuntimeInstance(self.project, str)]
        if issubclass(self.cls, (bytes, bytearray, range)):
            return [RuntimeInstance(self.project, int)]
        return []

    def subscript(self, index):
        if index is SLICE and issubclass(self.cls, (str, bytes, list, tuple)):
            return [self]
        if issubclass(self.cls, str):
            return [RuntimeInstance(self.project, str)]
        if issubclass(self.cls, (bytes, bytearray)):
            return [RuntimeInstance(self.project, int)]
        return []

    def builtin_type(self):
        return self.cls


class SequenceInstance(RuntimeInstance):
    """A list/tuple/set display whose elements are known expressions."""

    def __init__(self, project, cls, node, where):
        RuntimeInstance.__init__(self, project, cls)
        self._node = node
        self._where = where

    def key(self):
        return ("display", id(self._node))

    def _analysis(self):
        return self._where.scope.tree.analysis

    def iterate(self):
        result = []
        for element in self._node.elts:
            if not isinstance(element, ast.Starred):
                result.extend(self._analysis().evaluate(element, self._where))
        return _unique(result)

    def subscript(self, index):
        if index is SLICE:
            return [self]
        elements = self._node.elts
        if isinstance(index, int) and not isinstance(index, bool) \
                and not any(isinstance(e, ast.Starred) for e in elements) \
                and -len(elements) <= index < len(elements) and self.cls is not set:
            return self._analysis().evaluate(elements[index], self._where)
        if self.cls is set:
            return []
        return self.iterate()


class DictInstance(RuntimeInstance):
    """A dict display whose keys and values are known expressions."""

    def __init__(self, project, node, where):
        RuntimeInstance.__init__(self, project, dict)
        self._node = node
        self._where = where

    def key(self):
        return ("display", id(self._node))

    def iterate(self):
        analysis = self._where.scope.tree.analysis
        result = []
        for key in self._node.keys:
            if key is not None:
                result.extend(analysis.evaluate(key, self._where))
        return _unique(result)

    def subscript(self, index):
        analysis = self._where.scope.tree.analysis
        result = []
        for key, value in zip(self._node.keys, self._node.values):
            if key is None:
                continue
            if isinstance(key, ast.Constant) and index is not UNKNOWN_INDEX \
                    and index is not SLICE:
                if key.value == index and type(key.value) is type(index):
                    return analysis.evaluate(value, self._where)
                continue
            result.extend(analysis.evaluate(value, self._where))
        if index is UNKNOWN_INDEX:
            result = []
            for key, value in zip(self._node.keys, self._node.values):
                if key is not None:
                    result.extend(analysis.evaluate(value, self._where))
        return _unique(result)


class UnresolvedModule(Value):
    kind = MODULE


class DirectoryModule(Value):
    """A package directory without ``__init__.py``."""

    kind = MODULE

    def __init__(self, project, directory):
        self.project = project
        self.directory = directory

    def key(self):
        return ("directory", self.directory)

    def attribute(self, name):
        found = self.project.submodule_value(self.directory, name)
        return [found] if found is not None else []

    def attribute_targets(self, name):
        return [_ValueTarget(v) for v in self.attribute(name)]


class StaticModule(Value):
    kind = MODULE

    def __init__(self, analysis):
        self.analysis = analysis

    def key(self):
        return ("module", self.analysis.path)

    def members(self):
        return self.analysis.module_members()

    def attribute_targets(self, name):
        analysis = self.analysis
        targets = [t for t, _ in analysis.resolve_local(name, Where(analysis.tree.module))]
        if targets:
            return targets
        package_dir = analysis.package_dir()
        if package_dir:
            found = analysis.project.submodule_value(package_dir, name)
            if found is not None:
                return [_ValueTarget(found)]
        return []

    def attribute(self, name):
        result = []
        for target in self.attribute_targets(name):
            result.extend(self.analysis.target_values(target))
        return _unique(result)


class StaticFunction(Value):
    kind = FUNCTION

    def __init__(self, analysis, scope):
        self.analysis = analysis
        self.scope = scope

    def key(self):
        return ("function", id(self.scope))

    def is_property(self):
        return any(name in _PROPERTY_DECORATORS for name in self.scope.decorator_names())

    def call(self):
        if self.scope.is_async():
            return []
        project = self.analysis.project
        key = ("call", id(self.scope))
        if not project.enter(key):
            return []
        try:
            return self._returns()
        finally:
            project.leave(key)

    def _returns(self):
        analysis = self.analysis
        statements = self.scope.return_statements()
        if statements is None:
            return [RuntimeInstance(analysis.project, types.GeneratorType)]
        result = []
        for statement in statements:
            if statement.value is None:
                result.append(analysis.none_value())
            else:
                where = analysis.where_before(self.scope, statement)
                result.extend(analysis.evaluate(statement.value, where))
        if not statements:
            result.append(analysis.none_value())
        result = _unique(result)
        if not result and self.scope.node.returns is not None:
            where = analysis.where_before(self.scope.parent, self.scope.node)
            result = analysis.annotation_values(self.scope.node.returns, where)
        return result


class StaticClass(Value):
    kind = CLASS

    def __init__(self, analysis, scope):
        self.analysis = analysis
        self.scope = scope
        self.name = scope.name

    def key(self):
        return ("class", id(self.scope))

    def bases(self):
        project = self.analysis.project
        key = ("bases", id(self.scope))
        if not project.enter(key):
            return []
        try:
            where = self.analysis.where_before(self.scope.parent, self.scope.node)
            result = []
            for expr in self.scope.base_expressions():
                for value in self.analysis.evaluate(expr, where):
                    if isinstance(value, StaticClass) and value.key() != self.key():
                        result.append(value)
            return _unique(result)
        finally:
            project.leave(key)

    def mro(self):
        return _linearize(self, set())

    def members(self):
        result = {}
        for cls in reversed(self.mro()):
            for event in cls.scope.all_events():
                if event.name and event.form != scopes.STAR:
                    result[event.name] = BindingEntity(cls.analysis, event)
        return result

    def instance_members(self):
        result = self.members()
        grouped = {}
        for cls in reversed(self.mro()):
            for event in cls.scope.instance_attribute_events():
                grouped.setdefault(event.name, []).append(event)
        for name, events in grouped.items():
            result[name] = AttributeEntity(self.analysis, events)
        return result

    def class_targets(self, name):
        for cls in self.mro():
            targets = [t for t, _ in cls.analysis.resolve_local(name, Where(cls.scope))]
            if targets:
                return targets
        return []

    def instance_targets(self, name):
        targets = []
        for cls in self.mro():
            targets.extend(e for e in cls.scope.instance_attribute_events() if e.name == name)
        return targets

    def attribute_targets(self, name):
        return self.class_targets(name)

    def attribute(self, name):
        result = []
        for target in self.class_targets(name):
            result.extend(self.analysis.target_values(target))
        return _unique(result)

    def call(self):
        return self.instantiate()

    def instantiate(self):
        return [StaticInstance(self)]

    def subscript(self, index):
        return [self]

    def is_subclass_of(self, other):
        return any(cls.key() == other.key() for cls in self.mro())


class StaticInstance(Value):
    kind = INSTANCE

    def __init__(self, cls):
        self.cls = cls
        self.type_name = cls.name

    def key(self):
        return ("static-instance", self.cls.key())

    def members(self):
        return self.cls.instance_members()

    def attribute_targets(self, name):
        return self.cls.instance_targets(name) or self.cls.class_targets(name)

    def attribute(self, name):
        analysis = self.cls.analysis
        project = analysis.project
        key = ("attribute", self.cls.key(), name)
        if not project.enter(key):
            return []
        try:
            instance_targets = self.cls.instance_targets(name)
            result = []
            for target in instance_targets or self.cls.class_targets(name):
                for value in analysis.target_values(target):
                    if not instance_targets and isinstance(value, StaticFunction) \
                            and value.is_property():
                        result.extend(value.call())
                    else:
                        result.append(value)
            return _unique(result)
        finally:
            project.leave(key)

    def _dunder_call(self, name):
        result = []
        for value in self.attribute(name):
            result.extend(value.call())
        return _unique(result)

    def call(self):
        return self._dunder_call("__call__")

    def iterate(self):
        result = []
        for iterator in self._dunder_call("__iter__"):
            if isinstance(iterator, StaticInstance):
                result.extend(iterator._dunder_call("__next__"))
            else:
                result.extend(iterator.iterate())
        return _unique(result)

    def subscript(self, index):
        return self._dunder_call("__getitem__")


class _ValueTarget:
    """A resolution target that is directly a value (e.g. a submodule)."""

    def __init__(self, value):
        self.value = value


def _linearize(cls, seen):
    """C3 linearization of statically known classes (DFS on conflict)."""
    if cls.key() in seen:
        return [cls]
    seen = seen | {cls.key()}
    bases = cls.bases()
    sequences = [_linearize(base, seen) for base in bases] + [list(bases)]
    result = [cls]
    sequences = [list(s) for s in sequences if s]
    while sequences:
        for sequence in sequences:
            head = sequence[0]
            if not any(head.key() in [c.key() for c in s[1:]] for s in sequences):
                break
        else:
            for sequence in sequences:
                for item in sequence:
                    if item.key() not in [c.key() for c in result]:
                        result.append(item)
            return result
        result.append(head)
        sequences = [[c for c in s if c.key() != head.key()] for s in sequences]
        sequences = [s for s in sequences if s]
    return result


# ---------------------------------------------------------------------------
# Entities

class Entity:
    name = None

    def presentation(self):
        return (STATEMENT, None)

    def values(self):
        return []


class RuntimeEntity(Entity):
    """An attribute of a live object, or of a class standing in for an instance."""

    def __init__(self, project, name, owner, from_class=None):
        self.project = project
        self.name = name
        self._owner = owner
        self._from_class = from_class

    def fetch(self):
        if self._owner is not None:
            return introspect.get_attribute(self._owner, self.name)
        ok, obj = introspect.get_attribute(self._from_class, self.name)
        if ok and introspect.is_data_descriptor(obj):
            return False, None
        return ok, obj

    def owner_name(self):
        """Qualified name of the object or class this is an attribute of."""
        owner = self._from_class if self._from_class is not None else self._owner
        if isinstance(owner, types.ModuleType):
            return owner.__name__
        if not isinstance(owner, type):
            owner = type(owner)
        return "%s.%s" % (owner.__module__, owner.__qualname__)

    def presentation(self):
        ok, obj = self.fetch()
        if not ok:
            return (STATEMENT, None)
        kind = introspect.kind_of(obj)
        if kind == INSTANCE:
            return (INSTANCE, introspect.type_name(obj))
        return (kind, None)

    def values(self):
        ok, obj = self.fetch()
        if not ok:
            return []
        owner = self._from_class
        if owner is None:
            owner = self._owner if isinstance(self._owner, type) else type(self._owner)
        return [RuntimeValue(self.project, obj, owner)]


class BindingEntity(Entity):
    def __init__(self, analysis, binding):
        self._analysis = analysis
        self.binding = binding
        self.name = binding.name

    def presentation(self):
        form = self.binding.form
        if form == scopes.DEF:
            return (FUNCTION, None)
        if form == scopes.CLASS:
            return (CLASS, None)
        if form == scopes.PARAM:
            return (PARAM, None)
        if form == scopes.IMPORT:
            return (MODULE, None)
        if form in (scopes.IMPORT_FROM, scopes.ASSIGN, scopes.EXCEPT):
            values = self.values()
            value = values[0] if values else Value()
            if value.kind == INSTANCE:
                return (INSTANCE, value.type_name)
            if form == scopes.IMPORT_FROM and value.kind in (MODULE, CLASS, FUNCTION):
                return (value.kind, None)
        return (STATEMENT, None)

    def values(self):
        return self._analysis.binding_values(self.binding)


class AttributeEntity(Entity):
    """An instance attribute assigned (possibly several times) in methods."""

    def __init__(self, analysis, bindings):
        self._analysis = analysis
        self.bindings = bindings
        self.name = bindings[0].name

    def presentation(self):
        values = self.values()
        if values and values[0].kind == INSTANCE:
            return (INSTANCE, values[0].type_name)
        return (STATEMENT, None)

    def values(self):
        result = []
        for binding in self.bindings:
            result.extend(self._analysis.binding_values(binding))
        return _unique(result)


# ---------------------------------------------------------------------------
# Analysis of one file

class Analysis:
    """Inference over one source file."""

    def __init__(self, project, path, text):
        self.project = project
        self.path = path
        self.tree = scopes.ScopeTree(text, path)
        self.tree.analysis = self
        self._scope_by_node = {}
        self._index(self.tree.module)
        self._module_members = None
        self._flows = {}
        self._binding_cache = {}

    def _index(self, scope):
        for child in scope.children:
            self._scope_by_node[id(child.node)] = child
            self._index(child)

    def scope_of(self, node):
        return self._scope_by_node.get(id(node))

    def package_dir(self):
        if os.path.basename(self.path) == "__init__.py":
            return os.path.dirname(self.path)
        return None

    def location(self, line, col, indent):
        return Location(self, self.tree.scope_at(line, col), line, col, indent)

    def none_value(self):
        return RuntimeInstance(self.project, type(None))

    # -- flow ------------------------------------------------------------
    def flow(self, scope):
        analysis = scope.tree.analysis
        if analysis is not self:
            return analysis.flow(scope)
        found = self._flows.get(id(scope))
        if found is None:
            found = self._flows[id(scope)] = flow.Flow(scope)
        return found

    def where_before(self, scope, node):
        return Where(scope, self.flow(scope).state_before(node))

    # -- members ---------------------------------------------------------
    def module_members(self):
        if self._module_members is None:
            key = ("module", self.path)
            if not self.project.enter(key):
                return {}
            try:
                result = {}
                for event in self.tree.module.all_events():
                    self._apply(result, event)
                self._module_members = result
            finally:
                self.project.leave(key)
        return self._module_members

    def _apply(self, result, event):
        if event.form == scopes.STAR:
            result.update(self.star_members(event))
        elif event.name:
            result[event.name] = BindingEntity(self, event)

    def star_members(self, event):
        module = self.project.module_value(event.details["module"], event.details["level"],
                                           self.path)
        if module is None:
            return {}
        return {name: entity for name, entity in module.members().items()
                if not name.startswith("_")}

    def visible(self, scope, line):
        result = {name: RuntimeEntity(self.project, name, vocabulary.builtin_namespace())
                  for name in vocabulary.builtin_names()}
        for level in reversed(scope.chain()):
            for event in level.events_until_line(line):
                self._apply(result, event)
        return result

    # -- name resolution -------------------------------------------------
    def resolve(self, name, where):
        """Targets ``name`` may refer to at ``where``: list of (target, constraints)."""
        scope = where.scope
        if scope.parent is not None and name in scope.globals_declared:
            module = scope
            while module.parent is not None:
                module = module.parent
            return self.resolve(name, Where(module))
        state = where.state if where.state is not None else self.flow(scope).end
        facts = state.facts(name)
        if facts:
            result = []
            for binding, constraints in sorted(facts, key=_fact_order):
                if binding is flow.OUTER:
                    for target, more in self._resolve_outer(name, scope):
                        result.append((target, more + constraints))
                else:
                    result.append((binding, constraints))
            return result
        for event in reversed(scope.events):
            if event.form == scopes.STAR:
                members = scope.tree.analysis.star_members(event)
                if name in members:
                    return [(members[name], ())]
        return self._resolve_outer(name, scope)

    def resolve_local(self, name, where):
        """Like ``resolve`` but without looking outside ``where.scope``."""
        state = where.state if where.state is not None else self.flow(where.scope).end
        facts = state.facts(name)
        if facts:
            return [(b, c) for b, c in sorted(facts, key=_fact_order) if b is not flow.OUTER]
        for event in reversed(where.scope.events):
            if event.form == scopes.STAR:
                members = where.scope.tree.analysis.star_members(event)
                if name in members:
                    return [(members[name], ())]
        return []

    def _resolve_outer(self, name, scope):
        parent = scope.parent
        while parent is not None and parent.kind == scopes.Scope.CLASS:
            parent = parent.parent
        if parent is None:
            if name in vocabulary.builtin_names():
                return [(RuntimeEntity(self.project, name, vocabulary.builtin_namespace()), ())]
            return []
        state = None
        if scope.kind == scopes.Scope.CLASS and scope.parent is parent:
            state = self.flow(parent).state_before(scope.node)
        return self.resolve(name, Where(parent, state))

    def target_values(self, target):
        if isinstance(target, scopes.Binding):
            return target.home.tree.analysis.binding_values(target)
        if isinstance(target, _ValueTarget):
            return [target.value]
        return target.values()

    def name_values(self, name, where):
        result = []
        for target, constraints in self.resolve(name, where):
            values = self.target_values(target)
            if constraints:
                values = self.narrow(values, constraints, where)
            result.extend(values)
        return _unique(result)

    def narrow(self, values, constraints, where):
        for constraint in constraints:
            if constraint.kind == flow.Constraint.NONE:
                if constraint.positive:
                    values = [self.none_value()]
                else:
                    values = [v for v in values if v.builtin_type() is not type(None)]
                continue
            classes = [c for c in self._class_values(constraint.expr, where)]
            if not classes:
                continue
            if constraint.positive:
                values = _unique([i for c in classes for i in c.instantiate()])
            else:
                values = [v for v in values if not any(_is_instance(v, c) for c in classes)]
        return values

    def _class_values(self, expr, where):
        if isinstance(expr, ast.Tuple):
            found = []
            for element in expr.elts:
                found.extend(self._class_values(element, where))
            return found
        return [v for v in self.evaluate(expr, where) if v.kind == CLASS]

    # -- bindings --------------------------------------------------------
    def binding_values(self, binding):
        cached = self._binding_cache.get(id(binding))
        if cached is not None:
            return cached
        key = ("binding", id(binding))
        if not self.project.enter(key):
            return []
        try:
            result = _unique(self._binding_values(binding))
        finally:
            self.project.leave(key)
        self._binding_cache[id(binding)] = result
        return result

    def _binding_values(self, binding):
        form, details = binding.form, binding.details
        if form == scopes.DEF:
            return [StaticFunction(self, self._scope_by_node[id(details["node"])])] \
                if "node" in details else [StaticFunction(self, self.scope_of(binding.node))]
        if form == scopes.CLASS:
            return [StaticClass(self, self.scope_of(binding.node))]
        if form == scopes.PARAM:
            return self._param_values(binding)
        if form == scopes.IMPORT:
            found = self.project.module_value(details["module"], 0, self.path)
            return [found] if found is not None else []
        if form == scopes.IMPORT_FROM:
            return self._import_from_values(details)
        where = self.where_before(binding.home, binding.stmt) if binding.stmt is not None \
            else Where(binding.home)
        if form == scopes.ASSIGN:
            if details.get("annotation") is not None:
                annotated = self.annotation_values(details["annotation"], where)
                if annotated:
                    return annotated
            return self._unpacked(details.get("value"), details.get("path", ()), where)
        if form == scopes.OTHER and details.get("value") is not None:
            values = self.evaluate(details["value"], where)
            if details.get("source") == "for":
                values = [item for value in values for item in value.iterate()]
            elif details.get("source") == "with":
                values = [entered for value in values for entered in _entered(value)]
            return self._index_path(values, details.get("path", ()))
        if form == scopes.EXCEPT and details["type_expr"] is not None:
            return [i for c in self._class_values(details["type_expr"], where)
                    for i in c.instantiate()]
        return []

    def _unpacked(self, expr, path, where):
        if expr is None:
            return []
        direct = _unpack(expr, path)
        if direct is not None:
            return self.evaluate(direct, where)
        return self._index_path(self.evaluate(expr, where), path)

    @staticmethod
    def _index_path(values, path):
        for index in path:
            values = _unique([item for value in values for item in value.subscript(index)])
        return values

    def _param_values(self, binding):
        details = binding.details
        function = details["function"]
        owner = function.class_scope()
        if details["index"] == 0 and owner is not None and not details["star"]:
            decorators = function.decorator_names()
            if "staticmethod" not in decorators:
                cls = StaticClass(self, owner)
                return [cls] if "classmethod" in decorators else cls.instantiate()
        if details["star"] == "*":
            return [RuntimeInstance(self.project, tuple)]
        if details["star"] == "**":
            return [RuntimeInstance(self.project, dict)]
        where = self.where_before(function.parent, function.node)
        if details["annotation"] is not None:
            annotated = self.annotation_values(details["annotation"], where)
            if annotated:
                return annotated
        if details.get("default") is not None:
            return self.evaluate(details["default"], where)
        return []

    def _import_from_values(self, details):
        module_name, level, attr = details["module"], details["level"], details["attr"]
        module = self.project.module_value(module_name, level, self.path)
        if module is not None:
            values = module.attribute(attr)
            if values:
                return values
        dotted = module_name + "." + attr if module_name else attr
        sub = self.project.module_value(dotted, level, self.path)
        return [sub] if sub is not None else []

    def import_from_targets(self, binding):
        """Where an imported name is bound in its own module."""
        details = binding.details
        module = self.project.module_value(details["module"], details["level"], self.path)
        if module is not None:
            targets = module.attribute_targets(details["attr"])
            if targets:
                return targets
        return []

    # -- annotations -----------------------------------------------------
    def annotation_values(self, node, where):
        if isinstance(node, ast.Constant):
            if node.value is None:
                return [self.none_value()]
            if isinstance(node.value, str):
                try:
                    parsed = ast.parse(node.value.strip(), mode="eval").body
                except (SyntaxError, ValueError, RecursionError, MemoryError):
                    return []
                return self.annotation_values(parsed, where)
            return []
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitOr):
            return _unique(self.annotation_values(node.left, where)
                           + self.annotation_values(node.right, where))
        if isinstance(node, ast.Subscript):
            head = _terminal_name(node.value)
            args = node.slice.elts if isinstance(node.slice, ast.Tuple) else [node.slice]
            if head == "Optional":
                return _unique(self.annotation_values(args[0], where) + [self.none_value()])
            if head == "Union":
                return _unique([v for a in args for v in self.annotation_values(a, where)])
            if head in ("Annotated", "ClassVar", "Final", "Required", "NotRequired",
                        "ReadOnly"):
                return self.annotation_values(args[0], where)
            if head in ("Type", "type"):
                return [v for v in self.evaluate(args[0], where) if v.kind == CLASS]
            return self._instances_of(self.evaluate(node.value, where))
        return self._instances_of(self.evaluate(node, where))

    def _instances_of(self, values):
        result = []
        for value in values:
            if value.kind == CLASS:
                result.extend(value.instantiate())
            elif isinstance(value, RuntimeValue):
                origin = getattr(value.obj, "__origin__", None)
                if isinstance(origin, type):
                    result.append(RuntimeInstance(self.project, origin))
        return _unique(result)

    # -- expressions -----------------------------------------------------
    def evaluate(self, node, where):
        project = self.project
        if isinstance(node, ast.Constant):
            return [RuntimeInstance(project, type(node.value))]
        sequence = _SEQUENCE_TYPES.get(type(node))
        if sequence is not None:
            return [SequenceInstance(project, sequence, node, where)]
        if isinstance(node, ast.Dict):
            return [DictInstance(project, node, where)]
        literal = _LITERAL_TYPES.get(type(node))
        if literal is not None:
            return [RuntimeInstance(project, literal)]
        if isinstance(node, ast.Name):
            return self.name_values(node.id, where)
        if isinstance(node, ast.Attribute):
            result = []
            for value in self.evaluate(node.value, where):
                result.extend(value.attribute(node.attr))
            return _unique(result)
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name) and node.func.id == "super":
                found = self._super_values(where)
                if found is not None:
                    return found
            result = []
            for value in self.evaluate(node.func, where):
                result.extend(value.call())
            return _unique(result)
        if isinstance(node, ast.Subscript):
            index = _index_of(node.slice)
            result = []
            for value in self.evaluate(node.value, where):
                result.extend(value.subscript(index))
            return _unique(result)
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return [RuntimeInstance(project, bool)]
            return self.evaluate(node.operand, where)
        if isinstance(node, ast.BinOp):
            return self._binary(node, where)
        if isinstance(node, ast.BoolOp):
            return _unique([v for operand in node.values for v in self.evaluate(operand, where)])
        if isinstance(node, ast.IfExp):
            return _unique(self.evaluate(node.body, where) + self.evaluate(node.orelse, where))
        if isinstance(node, ast.NamedExpr):
            return self.evaluate(node.value, where)
        return []

    def _binary(self, node, where):
        result = []
        lefts = self.evaluate(node.left, where)
        rights = None
        for left in lefts:
            left_type = left.builtin_type()
            if left_type is str and isinstance(node.op, ast.Mod):
                result.append(left)
                continue
            if rights is None:
                rights = self.evaluate(node.right, where)
            for right in rights:
                if left_type is not None and left_type is right.builtin_type() \
                        and left_type in _ARITHMETIC_TYPES:
                    result.append(RuntimeInstance(self.project, left_type))
        return _unique(result)

    def _super_values(self, where):
        scope = where.scope
        owner = scope.class_scope() if scope.kind == scopes.Scope.FUNCTION else None
        if owner is None:
            return None
        cls = StaticClass(owner.tree.analysis, owner)
        return [i for base in cls.bases() for i in base.instantiate()]


def _fact_order(fact):
    binding = fact[0]
    return getattr(binding, "order", 0)


def _is_instance(value, cls):
    if isinstance(value, StaticInstance) and isinstance(cls, StaticClass):
        return value.cls.is_subclass_of(cls)
    if isinstance(cls, RuntimeValue) and value.builtin_type() is not None:
        try:
            return issubclass(value.builtin_type(), cls.obj)
        except TypeError:
            return False
    return False


def _entered(value):
    if isinstance(value, StaticInstance):
        entered = value._dunder_call("__enter__")
        if entered:
            return entered
    return [value]


def _terminal_name(node):
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    return None


def _index_of(node):
    if isinstance(node, ast.Slice):
        return SLICE
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub) \
            and isinstance(node.operand, ast.Constant) and isinstance(node.operand.value, int):
        return -node.operand.value
    return UNKNOWN_INDEX


def _unpack(expr, path):
    for index in path:
        if not isinstance(expr, (ast.Tuple, ast.List)):
            return None
        if any(isinstance(e, ast.Starred) for e in expr.elts) or index >= len(expr.elts):
            return None
        expr = expr.elts[index]
    return expr


class Location:
    """A cursor position inside the main file (for completion)."""

    def __init__(self, analysis, scope, line, col, indent):
        self._analysis = analysis
        self._scope = scope
        self._line = line
        self._where = Where(scope, analysis.flow(scope).state_at(line, col, indent))

    def visible_entities(self):
        return self._analysis.visible(self._scope, self._line)

    def evaluate(self, expression_text):
        """Possible values of an expression written at the cursor."""
        try:
            node = ast.parse(expression_text.strip(), mode="eval").body
        except (SyntaxError, ValueError, RecursionError, MemoryError):
            return []
        return self._analysis.evaluate(node, self._where)


# ---------------------------------------------------------------------------
# Project

class Project:
    def __init__(self, main_path, main_text, root=None):
        self._main_path = os.path.abspath(main_path)
        self.root = os.path.abspath(root) if root else os.path.dirname(self._main_path)
        self._locator = ModuleLocator(self.root)
        self._analyses = {}
        self._active = set()
        self.main = Analysis(self, self._main_path, main_text)
        self._analyses[self._main_path] = self.main

    def enter(self, key):
        if key in self._active:
            return False
        self._active.add(key)
        return True

    def leave(self, key):
        self._active.discard(key)

    def location(self, line, col, indent=0):
        return self.main.location(line, col, indent)

    def module_value(self, dotted, level=0, importer_path=None):
        located = self._locator.locate(dotted, level, importer_path or self._main_path)
        return self._wrap(located)

    def submodule_value(self, directory, name):
        return self._wrap(self._locator.locate_in_directory(directory, name))

    def _wrap(self, located):
        if located is None:
            return None
        if located.how == RUNTIME:
            return RuntimeValue(self, located.module)
        if located.how == DIRECTORY:
            return DirectoryModule(self, located.path)
        if located.how == SOURCE:
            return StaticModule(self._analysis_for(located.path))
        return None

    def _analysis_for(self, path):
        path = os.path.abspath(path)
        if path not in self._analyses:
            try:
                with open(path, "rb") as handle:
                    text = handle.read().decode("utf-8", errors="replace")
            except OSError:
                text = ""
            self._analyses[path] = Analysis(self, path, text)
        return self._analyses[path]

"""Definition navigation (``goto`` and ``infer``).

Secret: how the identifier under the cursor is found and classified (plain
name, attribute, definition header, parameter, import part, keyword
argument, comprehension variable), what each command answers for it, and
how bindings and values are described as definition records (names,
qualified names, positions, descriptions, docstrings).
"""

import ast
import inspect
import os
import re
import types

from . import inference, introspect, scopes
from .inference import (DictInstance, DirectoryModule, RuntimeEntity, RuntimeInstance,
                        RuntimeValue, StaticClass, StaticFunction, StaticInstance,
                        StaticModule, Where)
from .source import SourceFile

GOTO = "goto"
INFER = "infer"


class NotOnName(Exception):
    """The cursor does not touch an identifier."""


def run(command, path, line, col, root=None):
    """Definitions (as dicts) answering ``command`` at the cursor."""
    source = SourceFile(path)
    source.check_position(line, col)
    project = inference.Project(source.path, source.text(), root)
    analysis = project.main
    occurrence = _Finder(analysis, line, col).find()
    if occurrence is None:
        raise NotOnName("no name at %d:%d" % (line, col))
    describer = _Describer(project)
    if command == GOTO:
        records = describer.targets(occurrence.goto())
    else:
        records = describer.values(occurrence.infer())
    unique = {}
    for record in records:
        if record is not None:
            unique.setdefault(tuple(sorted(record.items())), record)
    return sorted(unique.values(),
                  key=lambda r: (r["module_path"], r["line"], r["column"], r["name"]))


# ---------------------------------------------------------------------------
# Finding the identifier under the cursor

class _Occurrence:
    """One identifier in the main file and what it means."""

    def __init__(self, analysis, kind, node, scope, stmt, **extra):
        self.analysis = analysis
        self.kind = kind
        self.node = node
        self.scope = scope
        self.stmt = stmt
        self.extra = extra

    def where(self):
        if self.stmt is None:
            return Where(self.scope)
        return self.analysis.where_before(self.scope, self.stmt)

    # Results: goto gives targets (Bindings, Entities, value targets), infer values.
    def goto(self):
        return self._answer(GOTO)

    def infer(self):
        return self._answer(INFER)

    def _answer(self, command):
        analysis = self.analysis
        kind = self.kind
        binding = self.extra.get("binding")
        if binding is not None:
            if command == GOTO:
                return [binding]
            return analysis.binding_values(binding)
        if kind == "name":
            return self._name(command, self.node.id, self.where())
        if kind == "global":
            module = self.scope
            while module.parent is not None:
                module = module.parent
            return self._name(command, self.extra["name"], Where(module))
        if kind == "attr":
            receivers = analysis.evaluate(self.node.value, self.where())
            result = []
            for receiver in receivers:
                if command == GOTO:
                    result.extend(receiver.attribute_targets(self.node.attr))
                else:
                    result.extend(receiver.attribute(self.node.attr))
            return result
        if kind == "module":
            found = analysis.project.module_value(self.extra["dotted"], self.extra["level"],
                                                  analysis.path)
            if found is None:
                return []
            return [inference._ValueTarget(found)] if command == GOTO else [found]
        if kind == "imported":
            import_binding = self.extra["import_binding"]
            if command == GOTO:
                targets = analysis.import_from_targets(import_binding)
                if targets:
                    return targets
                return [inference._ValueTarget(v)
                        for v in analysis.binding_values(import_binding)]
            return analysis.binding_values(import_binding)
        if kind == "keyword":
            params = self._keyword_params()
            if command == GOTO:
                return params
            return [v for p in params for v in analysis.binding_values(p)]
        if kind == "comprehension":
            if command == GOTO:
                return [_ComprehensionTarget(self.analysis, self.extra["generator"],
                                             self.extra["target"])]
            values = analysis.evaluate(self.extra["generator"].iter, self.where())
            values = [item for value in values for item in value.iterate()]
            return analysis._index_path(values, self.extra["path"])
        return []

    def _name(self, command, name, where):
        analysis = self.analysis
        if command == GOTO:
            return [target for target, _ in analysis.resolve(name, where)]
        return analysis.name_values(name, where)

    def _keyword_params(self):
        analysis = self.analysis
        name = self.node.arg
        functions = []
        for value in analysis.evaluate(self.extra["call"].func, self.where()):
            if isinstance(value, StaticFunction):
                functions.append(value)
            elif isinstance(value, StaticClass):
                functions.extend(v for v in value.attribute("__init__")
                                 if isinstance(v, StaticFunction))
        params = []
        for function in functions:
            params.extend(e for e in function.scope.events
                          if e.form == scopes.PARAM and e.name == name)
        return params


class _ComprehensionTarget:
    def __init__(self, analysis, generator, target):
        self.analysis = analysis
        self.generator = generator
        self.target = target


class _Finder:
    """Walks the main file's syntax tree looking for the cursor's identifier."""

    def __init__(self, analysis, line, col):
        self.analysis = analysis
        self.tree = analysis.tree
        self.line = line
        self.col = col
        self.exact = None
        self.touching = None
        self.bindings = {}
        for binding in _all_bindings(self.tree.module):
            if binding.node is not None:
                self.bindings.setdefault(id(binding.node), binding)

    def find(self):
        module = self.tree.module
        for statement in module.node.body:
            self._walk(statement, module, None, {})
        return self.exact or self.touching

    def _check(self, line, start, name, make):
        if line != self.line or name is None:
            return
        end = start + len(name)
        if start <= self.col < end:
            if self.exact is None:
                self.exact = make()
        elif self.col == end and self.touching is None:
            self.touching = make()

    def _occurrence(self, kind, node, scope, stmt, **extra):
        return lambda: _Occurrence(self.analysis, kind, node, scope, stmt, **extra)

    def _bound(self, node, scope, stmt, fallback_kind="name"):
        binding = self.bindings.get(id(node))
        if binding is not None:
            return self._occurrence("binding", node, scope, stmt, binding=binding)
        return self._occurrence(fallback_kind, node, scope, stmt)

    def _walk(self, node, scope, stmt, comprehension):
        if node is None:
            return
        if isinstance(node, (ast.stmt, ast.ExceptHandler, ast.match_case)):
            stmt = node
        if not self._within(node):
            return
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            self._function(node, scope, stmt)
        elif isinstance(node, ast.ClassDef):
            for child in node.decorator_list + node.bases + node.keywords:
                self._walk(child, scope, stmt, comprehension)
            line, col = self.tree.definition_position(node)
            self._check(line, col, node.name, self._bound(node, scope, stmt))
            inner = self.analysis.scope_of(node) or scope
            for child in node.body:
                self._walk(child, inner, child, {})
        elif isinstance(node, ast.Lambda):
            args = node.args
            for default in args.defaults + [d for d in args.kw_defaults if d is not None]:
                self._walk(default, scope, stmt, comprehension)
            for arg in _arguments(args):
                self._check(arg.lineno, arg.col_offset, arg.arg,
                            self._occurrence("lambda", arg, scope, stmt))
            shadowed = {k: v for k, v in comprehension.items()
                        if k not in {a.arg for a in _arguments(args)}}
            self._walk(node.body, scope, stmt, shadowed)
        elif isinstance(node, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):
            self._comprehension(node, scope, stmt, comprehension)
        elif isinstance(node, ast.Name):
            if node.id in comprehension:
                generator, target, path = comprehension[node.id]
                make = self._occurrence("comprehension", node, scope, stmt,
                                        generator=generator, target=target, path=path)
            elif isinstance(node.ctx, ast.Store):
                make = self._bound(node, scope, stmt)
            else:
                make = self._occurrence("name", node, scope, stmt)
            self._check(node.lineno, node.col_offset, node.id, make)
        elif isinstance(node, ast.Attribute):
            self._walk(node.value, scope, stmt, comprehension)
            binding = self.bindings.get(id(node)) if isinstance(node.ctx, ast.Store) else None
            if binding is not None:
                make = self._occurrence("binding", node, scope, stmt, binding=binding)
            else:
                make = self._occurrence("attr", node, scope, stmt)
            self._check(node.end_lineno, node.end_col_offset - len(node.attr), node.attr, make)
        elif isinstance(node, ast.Call):
            self._walk(node.func, scope, stmt, comprehension)
            for arg in node.args:
                self._walk(arg, scope, stmt, comprehension)
            for keyword in node.keywords:
                if keyword.arg is not None:
                    self._check(keyword.lineno, keyword.col_offset, keyword.arg,
                                self._occurrence("keyword", keyword, scope, stmt, call=node))
                self._walk(keyword.value, scope, stmt, comprehension)
        elif isinstance(node, ast.Import):
            self._import(node, scope, stmt)
        elif isinstance(node, ast.ImportFrom):
            self._import_from(node, scope, stmt)
        elif isinstance(node, ast.ExceptHandler):
            self._walk(node.type, scope, stmt, comprehension)
            binding = self.bindings.get(id(node))
            if binding is not None:
                line, col = binding.position
                self._check(line, col, node.name, self._bound(node, scope, stmt))
            for child in node.body:
                self._walk(child, scope, child, comprehension)
        elif isinstance(node, (ast.Global, ast.Nonlocal)):
            col = node.col_offset
            for name in node.names:
                line, col = self.tree.find_identifier(name, node.lineno, col)
                kind = "global" if isinstance(node, ast.Global) else "name"
                target = ast.Name(id=name, ctx=ast.Load())
                self._check(line, col, name,
                            self._occurrence(kind, target, scope, stmt, name=name))
        elif isinstance(node, (ast.MatchAs, ast.MatchStar, ast.MatchMapping)):
            for child in ast.iter_child_nodes(node):
                self._walk(child, scope, stmt, comprehension)
            binding = self.bindings.get(id(node))
            if binding is not None:
                line, col = binding.position
                self._check(line, col, binding.name, self._bound(node, scope, stmt))
        else:
            for child in ast.iter_child_nodes(node):
                self._walk(child, scope, stmt, comprehension)

    def _within(self, node):
        first = getattr(node, "lineno", None)
        if first is None:
            return True
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) \
                and node.decorator_list:
            first = min(first, min(d.lineno for d in node.decorator_list))
        last = getattr(node, "end_lineno", None) or first
        return first <= self.line <= last

    def _function(self, node, scope, stmt):
        for child in node.decorator_list:
            self._walk(child, scope, stmt, {})
        args = node.args
        for default in args.defaults + [d for d in args.kw_defaults if d is not None]:
            self._walk(default, scope, stmt, {})
        inner = self.analysis.scope_of(node) or scope
        for arg in _arguments(args):
            self._walk(arg.annotation, scope, stmt, {})
            self._check(arg.lineno, arg.col_offset, arg.arg, self._bound(arg, inner, stmt))
        self._walk(node.returns, scope, stmt, {})
        line, col = self.tree.definition_position(node)
        self._check(line, col, node.name, self._bound(node, scope, stmt))
        for child in node.body:
            self._walk(child, inner, child, {})

    def _comprehension(self, node, scope, stmt, comprehension):
        visible = dict(comprehension)
        for generator in node.generators:
            self._walk(generator.iter, scope, stmt, visible)
            for name_node, path in _target_names(generator.target):
                visible[name_node.id] = (generator, name_node, path)
            self._walk(generator.target, scope, stmt, visible)
            for condition in generator.ifs:
                self._walk(condition, scope, stmt, visible)
        if isinstance(node, ast.DictComp):
            self._walk(node.key, scope, stmt, visible)
            self._walk(node.value, scope, stmt, visible)
        else:
            self._walk(node.elt, scope, stmt, visible)

    def _import(self, node, scope, stmt):
        for alias in node.names:
            binding = self.bindings.get(id(alias))
            parts = alias.name.split(".")
            col = alias.col_offset
            for index, part in enumerate(parts):
                dotted = ".".join(parts[: index + 1])
                if index == 0 and not alias.asname and binding is not None:
                    make = self._occurrence("binding", alias, scope, stmt, binding=binding)
                else:
                    make = self._occurrence("module", alias, scope, stmt, dotted=dotted, level=0)
                self._check(alias.lineno, col, part, make)
                col += len(part) + 1
            if alias.asname and binding is not None:
                line, col = binding.position
                self._check(line, col, alias.asname,
                            self._occurrence("binding", alias, scope, stmt, binding=binding))

    def _import_from(self, node, scope, stmt):
        if node.module:
            line, col = _module_position(self.tree, node)
            parts = node.module.split(".")
            for index, part in enumerate(parts):
                dotted = ".".join(parts[: index + 1])
                self._check(line, col, part, self._occurrence(
                    "module", node, scope, stmt, dotted=dotted, level=node.level))
                col += len(part) + 1
        for alias in node.names:
            binding = self.bindings.get(id(alias))
            if binding is None:
                continue
            if alias.asname:
                self._check(alias.lineno, alias.col_offset, alias.name, self._occurrence(
                    "imported", alias, scope, stmt, import_binding=binding))
                line, col = binding.position
                self._check(line, col, alias.asname,
                            self._occurrence("binding", alias, scope, stmt, binding=binding))
            else:
                self._check(alias.lineno, alias.col_offset, alias.name,
                            self._occurrence("binding", alias, scope, stmt, binding=binding))


def _module_position(tree, node):
    """Position of the module name in ``from <module> import ...``."""
    for number in range(node.lineno, (node.end_lineno or node.lineno) + 1):
        text = tree.line_text(number)
        start = node.col_offset if number == node.lineno else 0
        match = re.compile(r"\bfrom\s*\.*\s*").search(text, start)
        if match:
            return number, match.end()
    return node.lineno, node.col_offset


def _arguments(args):
    found = args.posonlyargs + args.args
    if args.vararg:
        found.append(args.vararg)
    found += args.kwonlyargs
    if args.kwarg:
        found.append(args.kwarg)
    return found


def _target_names(target, path=()):
    if isinstance(target, ast.Name):
        yield target, path
    elif isinstance(target, (ast.Tuple, ast.List)):
        for index, element in enumerate(target.elts):
            if isinstance(element, ast.Starred):
                for name, _ in _target_names(element.value):
                    yield name, None
            else:
                yield from _target_names(element, path + (index,))


def _all_bindings(scope):
    yield from scope.events
    yield from scope.instance_events
    for child in scope.children:
        yield from _all_bindings(child)


# ---------------------------------------------------------------------------
# Describing definitions

class _Describer:
    def __init__(self, project):
        self.project = project
        self.root = project.root

    # -- entry points ----------------------------------------------------
    def targets(self, targets):
        records = []
        for target in targets:
            if isinstance(target, scopes.Binding):
                records.append(self.binding(target))
            elif isinstance(target, inference.BindingEntity):
                records.append(self.binding(target.binding))
            elif isinstance(target, inference.AttributeEntity):
                records.extend(self.binding(b) for b in target.bindings)
            elif isinstance(target, RuntimeEntity):
                records.append(self.runtime_entity(target))
            elif isinstance(target, inference._ValueTarget):
                records.append(self.value(target.value))
            elif isinstance(target, _ComprehensionTarget):
                records.append(self.comprehension(target))
        return records

    def values(self, values):
        return [self.value(value) for value in values]

    # -- helpers ---------------------------------------------------------
    def relative(self, path):
        if not path:
            return ""
        path = os.path.abspath(path)
        relative = os.path.relpath(path, self.root)
        if relative.startswith(os.pardir + os.sep) or relative == os.pardir:
            return path
        return relative

    def module_name(self, path):
        relative = self.relative(path)
        if os.path.isabs(relative):
            relative = os.path.basename(relative)
        if relative.endswith(".py"):
            relative = relative[:-3]
        parts = [p for p in relative.replace(os.sep, "/").split("/") if p]
        if len(parts) > 1 and parts[-1] == "__init__":
            parts.pop()
        return ".".join(parts)

    def qualified(self, scope, name=None):
        names = []
        while scope is not None and scope.parent is not None:
            names.append(scope.name)
            scope = scope.parent
        tree = scope.tree if scope is not None else None
        prefix = [self.module_name(tree.path)] if tree is not None and tree.path else []
        result = prefix + list(reversed(names))
        if name is not None:
            result.append(name)
        return ".".join(p for p in result if p)

    @staticmethod
    def record(name, kind, full_name, module_path, line, column, description, docstring):
        return {"name": name, "type": kind, "full_name": full_name,
                "module_path": module_path, "line": line, "column": column,
                "description": description, "docstring": docstring or ""}

    # -- source definitions ----------------------------------------------
    def binding(self, binding):
        form = binding.form
        tree = binding.home.tree
        line, column = binding.position
        module_path = self.relative(tree.path)
        if form in (scopes.DEF, scopes.CLASS):
            scope = tree.analysis.scope_of(binding.node)
            if scope is not None:
                return self.scope_definition(scope)
        owner = binding.details.get("owner")
        if owner is not None:
            full_name = self.qualified(owner, binding.name)
        else:
            full_name = self.qualified(binding.scope, binding.name)
        if form == scopes.PARAM:
            return self.record(binding.name, "param", full_name, module_path, line, column,
                               "param %s" % binding.name, "")
        if form in (scopes.IMPORT, scopes.IMPORT_FROM):
            return self.import_binding(binding, module_path, line, column)
        return self.record(binding.name, "statement", full_name, module_path, line, column,
                           _statement_description(tree, binding), "")

    def import_binding(self, binding, module_path, line, column):
        analysis = binding.home.tree.analysis
        details = binding.details
        values = analysis.binding_values(binding)
        kind = "module"
        full_name = None
        if binding.form == scopes.IMPORT:
            full_name = details["module"]
        else:
            for value in values:
                if value.kind in (inference.MODULE, inference.CLASS, inference.FUNCTION,
                                  inference.INSTANCE):
                    kind = value.kind
                    break
            module = analysis.project.module_value(details["module"], details["level"],
                                                   analysis.path)
            prefix = None
            if isinstance(module, StaticModule):
                prefix = self.module_name(module.analysis.path)
            elif isinstance(module, RuntimeValue):
                prefix = getattr(module.obj, "__name__", None)
            if not prefix:
                prefix = details["module"] or ""
            full_name = "%s.%s" % (prefix, details["attr"]) if prefix else details["attr"]
        description = _import_text(binding.home.tree, binding.stmt)
        return self.record(binding.name, kind, full_name, module_path, line, column,
                           description, "")

    def scope_definition(self, scope, instance=False):
        node = scope.node
        tree = scope.tree
        line, column = tree.definition_position(node)
        full_name = self.qualified(scope)
        docstring = _docstring(node)
        module_path = self.relative(tree.path)
        if isinstance(node, ast.ClassDef):
            if instance:
                return self.record(node.name, "instance", full_name, module_path, line,
                                   column, "instance of %s" % node.name, docstring)
            return self.record(node.name, "class", full_name, module_path, line, column,
                               "class %s" % node.name, docstring)
        return self.record(node.name, "function", full_name, module_path, line, column,
                           "def %s(%s)" % (node.name, _parameters(node)), docstring)

    def comprehension(self, target):
        tree = target.analysis.tree
        node = target.target
        generator = target.generator
        description = "for %s in %s" % (_text(tree, generator.target),
                                        _text(tree, generator.iter))
        return self.record(node.id, "statement", self.qualified(tree.module, node.id),
                           self.relative(tree.path), node.lineno, node.col_offset,
                           description, "")

    # -- values ----------------------------------------------------------
    def value(self, value):
        if isinstance(value, StaticInstance):
            return self.scope_definition(value.cls.scope, instance=True)
        if isinstance(value, (StaticClass, StaticFunction)):
            return self.scope_definition(value.scope)
        if isinstance(value, StaticModule):
            path = value.analysis.path
            full_name = self.module_name(path)
            module = value.analysis.tree.module.node
            return self.record(full_name.split(".")[-1], "module", full_name,
                               self.relative(path), 1, 0, "module %s" % full_name.split(".")[-1],
                               _docstring(module))
        if isinstance(value, DirectoryModule):
            full_name = ".".join(p for p in self.relative(value.directory).split(os.sep) if p)
            name = full_name.split(".")[-1]
            return self.record(name, "module", full_name, self.relative(value.directory),
                               0, 0, "module %s" % name, "")
        if isinstance(value, (RuntimeInstance, DictInstance)):
            return self.runtime_instance(value.cls)
        if isinstance(value, RuntimeValue):
            return self.runtime_object(value.obj)
        return None

    def runtime_instance(self, cls):
        name = _type_name(cls)
        return self.record(name, "instance", "%s.%s" % (_type_module(cls), name), "", 0, 0,
                           "instance of %s" % name, "")

    def runtime_object(self, obj, name=None, full_name=None):
        kind = introspect.kind_of(obj)
        if kind == inference.INSTANCE:
            return self.runtime_instance(type(obj))
        if kind == inference.MODULE:
            module_name = getattr(obj, "__name__", name or "")
            short = module_name.split(".")[-1]
            return self.record(name or short, "module", module_name, "", 0, 0,
                               "module %s" % (name or short), "")
        if kind == inference.CLASS:
            own = _type_name(obj)
            full = full_name or "%s.%s" % (_type_module(obj),
                                           getattr(obj, "__qualname__", own))
            return self.record(name or own, "class", full, "", 0, 0,
                               "class %s" % (name or own), "")
        own = getattr(obj, "__name__", name or "")
        if full_name is None:
            module = getattr(obj, "__module__", None)
            qualname = getattr(obj, "__qualname__", own)
            if module is None and isinstance(getattr(obj, "__self__", None), type):
                module = obj.__self__.__module__
            full_name = "%s.%s" % (module, qualname) if module else qualname
        name = name or own
        return self.record(name, "function", full_name, "", 0, 0,
                           "def %s(%s)" % (name, _runtime_parameters(obj)), "")

    def runtime_entity(self, entity):
        ok, obj = entity.fetch()
        if not ok:
            return None
        full_name = "%s.%s" % (entity.owner_name(), entity.name)
        kind = introspect.kind_of(obj)
        if kind == inference.INSTANCE:
            if obj is None or isinstance(obj, (bool, int, float, str, bytes)):
                return self.runtime_instance(type(obj))
            name = _type_name(type(obj))
            return self.record(entity.name, "instance", full_name, "", 0, 0,
                               "instance of %s" % name, "")
        if kind == inference.MODULE:
            return self.runtime_object(obj, name=entity.name)
        return self.runtime_object(obj, name=entity.name, full_name=full_name)


def _type_name(cls):
    if cls is type(None):
        return "None"
    return getattr(cls, "__name__", "object")


def _type_module(cls):
    module = getattr(cls, "__module__", None) or "builtins"
    if cls in (type(None), types.GeneratorType, type(Ellipsis), type(NotImplemented)):
        return "builtins"
    return module


def _docstring(node):
    try:
        return ast.get_docstring(node, clean=True) or ""
    except (TypeError, AttributeError):
        return ""


def _parameters(node):
    try:
        return ast.unparse(node.args)
    except Exception:  # unparse may choke on repaired or odd trees
        return ", ".join(a.arg for a in _arguments(node.args))


def _runtime_parameters(obj):
    try:
        signature = inspect.signature(obj)
    except (TypeError, ValueError):
        return "..."
    text = str(signature)
    return text[1:text.rfind(")")] if text.startswith("(") else "..."


def _collapse(text):
    return re.sub(r"\s+", " ", text).strip()


def _text(tree, node):
    segment = tree.segment(node)
    if segment is None:
        try:
            segment = ast.unparse(node)
        except Exception:  # odd trees
            segment = ""
    return _collapse(segment)


def _import_text(tree, statement):
    if statement is None:
        return ""
    segment = tree.segment(statement)
    if segment is None or "\n" in segment:
        try:
            return ast.unparse(statement)
        except Exception:  # odd trees
            return _collapse(segment or "")
    return _collapse(segment)


def _statement_description(tree, binding):
    details = binding.details
    statement = binding.stmt
    if binding.form == scopes.ASSIGN and details.get("value") is not None:
        return _text(tree, details["value"])
    if statement is None:
        return binding.name
    if isinstance(statement, (ast.AnnAssign, ast.AugAssign, ast.Assign, ast.Expr)):
        return _text(tree, statement)
    if isinstance(statement, (ast.For, ast.AsyncFor)):
        return "for %s in %s" % (_text(tree, statement.target), _text(tree, statement.iter))
    if isinstance(statement, (ast.With, ast.AsyncWith)):
        return "with " + ", ".join(_text(tree, item.context_expr) + (
            " as " + _text(tree, item.optional_vars) if item.optional_vars else "")
            for item in statement.items)
    if isinstance(statement, ast.ExceptHandler):
        text = "except"
        if statement.type is not None:
            text += " " + _text(tree, statement.type)
        return text + (" as %s" % statement.name if statement.name else "")
    if isinstance(statement, ast.match_case):
        return "case " + _text(tree, statement.pattern)
    first = tree.line_text(statement.lineno)[statement.col_offset:]
    return _collapse(first).rstrip(":")

